mapper.select:
SELECT r.*, COALESCE(NULLIF(r.work_content, ''), p.name) AS work_content, p.name AS project_name FROM work_record r LEFT JOIN work_project p ON p.id = r.project_id
AND r.employee_id = #{employeeId}
AND r.status = #{status}
AND (r.work_content LIKE CONCAT('%', #{keyword}, '%') OR p.name LIKE CONCAT('%', #{keyword}, '%') OR r.employee_name LIKE CONCAT('%', #{keyword}, '%'))
AND r.work_date >= #{startDate}
AND r.work_date <= #{endDate}
ORDER BY r.work_date DESC, r.id DESC

SELECT r.employee_name AS employeeName, r.work_date AS workDate, COUNT(DISTINCT COALESCE(NULLIF(r.work_content, ''), p.name)) AS recordCount, COALESCE(SUM(r.work_hours), 0) AS totalWorkHours, COALESCE(SUM(r.overtime_hours), 0) AS totalOvertimeHours FROM work_record r LEFT JOIN work_project p ON p.id = r.project_id WHERE r.status = 'APPROVED'
AND r.work_date >= #{startDate}
AND r.work_date <= #{endDate}
GROUP BY r.employee_name, r.work_date ORDER BY r.work_date DESC, r.employee_name

SELECT COALESCE(SUM(work_hours), 0)
FROM work_record
WHERE employee_id = #{employeeId}
  AND work_date = #{workDate}
  AND status = 'APPROVED'

    AND id != #{excludeId}

SELECT *
FROM work_record
WHERE employee_id = #{employeeId}
  AND work_date = #{workDate}
ORDER BY id
